class Articulo {
  constructor(unidades) { this.unidades = unidades; }
  retirar(n) {
    if (!Number.isInteger(n) || n <= 0 || n > this.unidades) return false;
    this.unidades -= n;
    return true;
  }
}
const cable = new Articulo(4);
cable.retirar(3);
console.log(cable.retirar(2), cable.unidades);

